import re

def judge_faithfulness(context, statements):
    output = []
    for statement in statements:
        found = False
        for word in statement.split():
            if re.search(r'\b' + word + r'\b', context, re.IGNORECASE):
                found = True
                break
        if found:
            output.append({
                "statement": statement,
                "reason": f"The statement is mentioned in the context.",
                "verdict": 1
            })
